import type { AnimatedContentEaseFn } from './types';

const PI = Math.PI;
const TAU = PI * 2;

const POWERS: Record<string, number> = {
  power0: 0,
  linear: 0,
  power1: 1,
  quad: 1,
  power2: 2,
  cubic: 2,
  power3: 3,
  quart: 3,
  power4: 4,
  quint: 4,
  strong: 4,
};

function bounceOut(t: number): number {
  const n1 = 7.5625;
  const d1 = 2.75;
  if (t < 1 / d1) return n1 * t * t;
  if (t < 2 / d1) {
    const u = t - 1.5 / d1;
    return n1 * u * u + 0.75;
  }
  if (t < 2.5 / d1) {
    const u = t - 2.25 / d1;
    return n1 * u * u + 0.9375;
  }
  const u = t - 2.625 / d1;
  return n1 * u * u + 0.984375;
}

function elasticOut(amplitude = 1, period = 0.3): AnimatedContentEaseFn {
  const p1 = amplitude >= 1 ? amplitude : 1;
  const raw = period / (amplitude < 1 ? amplitude : 1);
  const p3 = (raw / TAU) * (Math.asin(1 / p1) || 0);
  const p2 = TAU / raw;
  return (t) =>
    t === 1 ? 1 : p1 * 2 ** (-10 * t) * Math.sin((t - p3) * p2) + 1;
}

function backOut(overshoot = 1.70158): AnimatedContentEaseFn {
  return (t) => {
    const u = t - 1;
    return u * u * ((overshoot + 1) * u + overshoot) + 1;
  };
}

/** Builds the "out" curve for an ease family; in / inOut are derived from it. */
function outCurve(name: string, args: number[]): AnimatedContentEaseFn | null {
  if (name in POWERS) {
    const n = POWERS[name]! + 1;
    return (t) => 1 - (1 - t) ** n;
  }
  switch (name) {
    case 'none':
      return (t) => t;
    case 'expo':
      return (t) => (t >= 1 ? 1 : 1 - 2 ** (-10 * t));
    case 'sine':
      return (t) => Math.sin((t * PI) / 2);
    case 'circ':
      return (t) => Math.sqrt(1 - (t - 1) ** 2);
    case 'back':
      return backOut(args[0]);
    case 'elastic':
      return elasticOut(args[0], args[1]);
    case 'bounce':
      return bounceOut;
    default:
      return null;
  }
}

/**
 * Parses a GSAP-style ease string such as 'power3.out', 'expo.inOut',
 * 'back.out(1.6)' or 'elastic.out(1, 0.55)'. Unknown names fall back to
 * power1.out, like GSAP's default.
 */
export function parseEase(value: string): AnimatedContentEaseFn {
  const match = /^([a-z]\w*)(?:\.(inOut|in|out))?(?:\(([^)]*)\))?$/i.exec(
    value.trim(),
  );
  const name = (match?.[1] ?? 'power1').toLowerCase();
  const type = match?.[2] ?? 'out';
  const args = (match?.[3] ?? '')
    .split(',')
    .map((part) => Number.parseFloat(part))
    .filter((n) => Number.isFinite(n));
  const out = outCurve(name, args) ?? outCurve('power1', []);
  if (!out) return (t) => t;
  if (name === 'none' || name === 'linear' || name === 'power0') return out;
  if (type === 'in') return (t) => 1 - out(1 - t);
  if (type === 'inOut') {
    return (t) =>
      t < 0.5 ? (1 - out(1 - 2 * t)) / 2 : 0.5 + out(2 * t - 1) / 2;
  }
  return out;
}

import type {
  AnimatedContentEaseFn,
  AnimatedContentPhase,
  AnimatedContentStaggerFrom,
  AnimatedContentState,
  AnimatedContentWipe,
} from './types';

const edge = (dir: string) =>
  `linear-gradient(${dir}, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))`;

export const WIPES: Record<Exclude<AnimatedContentWipe, 'none'>, string> = {
  up: edge('to top'),
  down: edge('to bottom'),
  left: edge('to left'),
  right: edge('to right'),
  center:
    'radial-gradient(farthest-corner at 50% 50%, #000 calc(var(--ac-wipe) * 140% - 40%), transparent calc(var(--ac-wipe) * 140%))',
};

export const REST: AnimatedContentState = {
  offset: 0,
  scale: 1,
  opacity: 1,
  blur: 0,
  rotate: 0,
  tilt: 0,
  wipe: 1,
};

/** GSAP `stagger: { each, from }` distribution, in seconds per target. */
export function staggerOffsets(
  count: number,
  each: number,
  from: AnimatedContentStaggerFrom,
): number[] {
  const mid = (count - 1) / 2;
  if (from === 'random') {
    const order = Array.from({ length: count }, (_, i) => i);
    for (let i = count - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [order[i], order[j]] = [order[j]!, order[i]!];
    }
    return order.map((rank) => rank * each);
  }
  return Array.from({ length: count }, (_, i) => {
    if (from === 'end') return (count - 1 - i) * each;
    if (from === 'center') return Math.abs(i - mid) * each;
    if (from === 'edges') return (mid - Math.abs(i - mid)) * each;
    return i * each;
  });
}

export function makePhase(
  from: AnimatedContentState,
  to: AnimatedContentState,
  starts: number[],
  duration: number,
  ease: AnimatedContentEaseFn,
): AnimatedContentPhase {
  const safe = Math.max(duration, 0.0001);
  return {
    from,
    to,
    starts,
    duration: safe,
    ease,
    total: Math.max(0, ...starts) + safe,
  };
}

/** State of target `index` at timeline time `time` (from-state before it starts). */
export function sample(
  phase: AnimatedContentPhase,
  index: number,
  time: number,
): AnimatedContentState {
  const local = Math.min(
    1,
    Math.max(0, (time - phase.starts[index]!) / phase.duration),
  );
  const k = phase.ease(local);
  const { from, to } = phase;
  return {
    offset: from.offset + (to.offset - from.offset) * k,
    scale: from.scale + (to.scale - from.scale) * k,
    opacity: from.opacity + (to.opacity - from.opacity) * k,
    blur: from.blur + (to.blur - from.blur) * k,
    rotate: from.rotate + (to.rotate - from.rotate) * k,
    tilt: from.tilt + (to.tilt - from.tilt) * k,
    wipe: from.wipe + (to.wipe - from.wipe) * k,
  };
}

export function applyState(
  el: HTMLElement,
  s: AnimatedContentState,
  horizontal: boolean,
  useBlur: boolean,
  usePerspective: boolean,
): void {
  const x = horizontal ? s.offset : 0;
  const y = horizontal ? 0 : s.offset;
  const tilt = horizontal ? `rotateY(${s.tilt}deg)` : `rotateX(${s.tilt}deg)`;
  el.style.transform = `${usePerspective ? 'perspective(900px) ' : ''}translate3d(${x}px, ${y}px, 0) rotate(${s.rotate}deg) ${tilt} scale(${s.scale})`;
  el.style.opacity = String(s.opacity);
  if (useBlur) el.style.filter = `blur(${Math.max(0, s.blur)}px)`;
  el.style.setProperty('--ac-wipe', String(s.wipe));
}

export function setMask(el: HTMLElement, mask: string | null): void {
  el.style.maskImage = mask ?? '';
  el.style.webkitMaskImage = mask ?? '';
}

/** Clears the animated props once the reveal lands, like GSAP clearProps. */
export function settle(el: HTMLElement, clearMask: boolean): void {
  el.style.removeProperty('transform');
  el.style.removeProperty('filter');
  el.style.removeProperty('--ac-wipe');
  if (clearMask) setMask(el, null);
}

/** Fully reverts everything the reveal wrote. */
export function revert(el: HTMLElement): void {
  settle(el, true);
  el.style.removeProperty('opacity');
}

export { default as AnimatedContent } from './AnimatedContent.vue';
export type {
  AnimatedContentDirection,
  AnimatedContentProps,
  AnimatedContentStaggerFrom,
  AnimatedContentTrigger,
  AnimatedContentWipe,
} from './types';

export type AnimatedContentDirection = 'vertical' | 'horizontal';

export type AnimatedContentWipe =
  | 'none'
  | 'up'
  | 'down'
  | 'left'
  | 'right'
  | 'center';

export type AnimatedContentStaggerFrom =
  | 'start'
  | 'end'
  | 'center'
  | 'edges'
  | 'random';

export type AnimatedContentTrigger = 'scroll' | 'mount';

export type AnimatedContentEaseFn = (t: number) => number;

export interface AnimatedContentProps {
  /** Scroll container that drives the animation, as a selector or an element. Defaults to the page. */
  container?: string | HTMLElement | null;
  /** How far the content travels into place, in px. */
  distance?: number;
  /** Axis the content travels along. */
  direction?: AnimatedContentDirection;
  /** Comes in from the other side: from above or from the left. */
  reverse?: boolean;
  /** Length of the animation, in seconds. */
  duration?: number;
  /** GSAP-style ease, such as 'expo.out', 'back.out(1.6)' or 'elastic.out(1, 0.5)'. */
  ease?: string;
  /** Opacity the content starts from. */
  initialOpacity?: number;
  /** Fades the content in. Off keeps it fully opaque while it moves. */
  animateOpacity?: boolean;
  /** Scale the content starts from. */
  scale?: number;
  /** Blur the content starts from, in px. */
  blur?: number;
  /** Rotation the content starts from, in degrees. */
  rotate?: number;
  /** Tips the content back in 3D, in degrees, so it flips up into place. */
  tilt?: number;
  /** Reveals the content behind a soft moving edge. */
  wipe?: AnimatedContentWipe;
  /** How far into the viewport the top of the content must be before it animates, 0 to 1. */
  threshold?: number;
  /** Wait before the animation starts, in seconds. */
  delay?: number;
  /** Animates each direct child in turn, this many seconds apart. */
  stagger?: number;
  /** Which child goes first when staggering. */
  staggerFrom?: AnimatedContentStaggerFrom;
  /** Animate when the content scrolls into view, or right away. */
  trigger?: AnimatedContentTrigger;
  /** Plays once. Off replays on every scroll in and reverses on scroll out. */
  once?: boolean;
  /** Ties the animation to the scroll position. A number smooths it, in seconds. */
  scrub?: boolean | number;
  /** Hides the content again this many seconds after it appears. 0 keeps it shown. */
  disappearAfter?: number;
  /** Length of the hide animation, in seconds. */
  disappearDuration?: number;
  /** GSAP-style ease of the hide animation. */
  disappearEase?: string;
  /** Extra classes for the wrapper. */
  class?: string;
}

export type AnimatedContentState = {
  offset: number;
  scale: number;
  opacity: number;
  blur: number;
  rotate: number;
  tilt: number;
  wipe: number;
};

export interface AnimatedContentPhase {
  from: AnimatedContentState;
  to: AnimatedContentState;
  /** Per-target start offsets, in seconds. */
  starts: number[];
  duration: number;
  ease: AnimatedContentEaseFn;
  total: number;
}
